-- Academy: rebuild Yachts Module 9 as "Build Your Career": 24 pages (11 with quick checks, 13 with answerable exercises
-- saved to the Broker Portfolio) + a 10-question final quiz. Same shape as the Module 1 migration.

do $mig$
declare
  v_module uuid;
  v_q uuid;
  v_page uuid;
  rec jsonb;
  n int := 0;
  i int;
  v_pages jsonb := $json$[{"heading": "Build Your Career", "body": "<p><b>Could I realistically enter this industry?</b></p><p>You now understand the yacht. You understand the market. You have practised client discovery, recommendations, communication, viewing and negotiation. Now comes the question every career changer eventually asks: <em>\"Could someone like me actually get into this industry?\"</em></p><p>The answer is not determined by whether you have spent your life around yachts. Many people enter new industries by recognising that the skills they already possess have value in a different environment. But yacht brokerage is not simply about wanting a glamorous career. It requires:</p><p>&bull; commercial discipline, communication and resilience<br/>&bull; follow-up and relationship building<br/>&bull; discretion, curiosity and organisation<br/>&bull; willingness to learn and comfort with uncertainty<br/>&bull; patience with long sales cycles<br/>&bull; the ability to build credibility over time</p><p>This module is about turning your existing experience into a realistic career proposition. You will not be told that yacht brokerage is \"easy to get into.\" You will be asked to work out: what can I already offer? What do I need to learn? Where could I fit? Who should I approach? What should I say? And what am I prepared to do to get my first opportunity?</p>", "q": "What is this module about?", "opts": ["Guaranteeing you a broker position", "Turning your existing experience into a realistic career proposition", "Learning yacht technical specifications", "Proving that brokerage is easy to enter"], "correct": 1}, {"heading": "Chapter 1: Is Yacht Brokerage Right for Me?", "body": "<p><b>Test the career itself</b></p><p>A career change is expensive in more ways than money. It costs time, energy, reputation, opportunity, emotional commitment and sometimes income stability. So don't begin with <em>\"How do I become a yacht broker?\"</em> Begin with: <b>\"What does the job actually require, and do I want that kind of working life?\"</b></p><p><b>What brokerage requires</b></p><p>&bull; <b>Relationship building:</b> with clients, other brokers, captains, crew, shipyards, surveyors, lawyers, managers, designers and industry contacts. Relationships take time.<br/>&bull; <b>Follow-up:</b> a client says <em>\"Let me think about it.\"</em> That is not the end. The broker must know when and how to follow up without becoming intrusive.<br/>&bull; <b>Commercial thinking:</b> price, value, positioning, competition, timing, negotiation and opportunity cost.<br/>&bull; <b>Resilience:</b> not every enquiry becomes a client, not every client buys, not every offer closes. A broker continues without letting every setback define the next conversation.<br/>&bull; <b>Discretion:</b> knowing what to say, what not to say, who needs to know and when to stop talking.<br/>&bull; <b>Self-management:</b> irregular schedules, travel, weekends, events, changing priorities and long preparation before a transaction closes.</p><p><b>The three-test rule</b></p><p>&bull; <b>Test 1, people:</b> would I still enjoy the job if yachts were removed and the day became mostly conversations, relationships and follow-up?<br/>&bull; <b>Test 2, commercial:</b> would I enjoy helping someone make a commercial decision involving significant money?<br/>&bull; <b>Test 3, process:</b> would I remain engaged when a transaction takes months and requires repeated follow-up?</p><p>If your answer is consistently no, don't ignore that information. It may mean you should explore another role within yachting.</p>", "q": "Where should a career change begin, according to this chapter?", "opts": ["With sending your CV to every brokerage", "With buying a yacht", "With choosing a job title", "With what the job actually requires and whether you want that working life"], "correct": 3}, {"heading": "Exercise: Career-Fit Check", "body": "<p><b>Rate yourself 1 to 5</b></p><p><b>1 = very uncomfortable, 3 = manageable, 5 = strongly comfortable.</b> This is not a scientific personality test. It is a conversation with yourself. Then apply the three-test rule.</p>", "exercise": {"intro": "Score each statement honestly, then answer the three tests.", "groups": [{"title": "Career-fit check", "section": "profile", "fields": [{"key": "cf_01", "label": "I enjoy meeting new people", "type": "rating"}, {"key": "cf_02", "label": "I am comfortable starting conversations", "type": "rating"}, {"key": "cf_03", "label": "I enjoy asking questions", "type": "rating"}, {"key": "cf_04", "label": "I can listen without immediately trying to solve the problem", "type": "rating"}, {"key": "cf_05", "label": "I am comfortable discussing money", "type": "rating"}, {"key": "cf_06", "label": "I can handle rejection", "type": "rating"}, {"key": "cf_07", "label": "I follow up reliably", "type": "rating"}, {"key": "cf_08", "label": "I enjoy learning technical subjects", "type": "rating"}, {"key": "cf_09", "label": "I can organise many moving parts", "type": "rating"}, {"key": "cf_10", "label": "I am comfortable when outcomes are uncertain", "type": "rating"}, {"key": "cf_11", "label": "I can protect confidential information", "type": "rating"}, {"key": "cf_12", "label": "I enjoy building relationships over time", "type": "rating"}, {"key": "cf_13", "label": "I can work independently", "type": "rating"}, {"key": "cf_14", "label": "I am comfortable representing myself professionally", "type": "rating"}, {"key": "cf_15", "label": "I can stay motivated without immediate results", "type": "rating"}]}, {"title": "The three-test rule", "section": "profile", "fields": [{"key": "cf_t1", "label": "Test 1, people: would I still enjoy the job if it were mostly conversations, relationships and follow-up?", "type": "long", "min": 30}, {"key": "cf_t2", "label": "Test 2, commercial: would I enjoy helping someone make a commercial decision involving significant money?", "type": "long", "min": 30}, {"key": "cf_t3", "label": "Test 3, process: would I stay engaged when a transaction takes months and needs repeated follow-up?", "type": "long", "min": 30}]}]}}, {"heading": "Chapter 2: Where Could I Fit?", "body": "<p><b>Brokerage is only one part of the industry</b></p><p>You have already seen the wider ecosystem. Now use it to think about your own fit. Possible career directions and their potential strengths:</p><p>&bull; <b>Yacht brokerage:</b> sales, relationships, negotiation, market knowledge and client management.<br/>&bull; <b>Charter brokerage:</b> hospitality, destination knowledge, itinerary planning, client service and sales.<br/>&bull; <b>Yacht management:</b> organisation, operations, administration, technical coordination and project management.<br/>&bull; <b>New build and shipyard sales:</b> project management, technical interest, commercial sales and long-term client relationships.<br/>&bull; <b>Yacht marketing:</b> writing, photography, digital marketing, brand development and communications.<br/>&bull; <b>Operations and administration:</b> organisation, process, documentation, coordination and attention to detail.<br/>&bull; <b>Crew and onboard careers:</b> hospitality, practical skills, seamanship, service and operational discipline.</p><p><b>Career discovery</b></p><p>Choose three yachting roles and, for each, work out what attracts you, what concerns you, what skills you have and need, what a typical week involves and what first opportunity you could realistically pursue. Then name the role you want to investigate most, not necessarily the role you will ultimately choose.</p>", "q": "What is the purpose of the career discovery exercise?", "opts": ["To compare several yachting roles and identify the one you most want to investigate, not to make a permanent choice", "To choose your final job title", "To rank roles by salary", "To avoid roles outside brokerage"], "correct": 0}, {"heading": "Exercise: Career Discovery", "body": "<p><b>Choose three yachting roles</b></p><p>For each: what attracts me, what concerns me, what skills I have, what skills I need, what a typical week involves and what first opportunity I could realistically pursue. Then name the role you want to investigate most.</p>", "exercise": {"intro": "Pick three roles. They do not all have to be brokerage.", "groups": [{"title": "Role 1", "section": "market", "fields": [{"key": "cd1_role", "label": "The role", "type": "short", "min": 6}, {"key": "cd1_attract", "label": "What attracts me?", "type": "long", "min": 20}, {"key": "cd1_concern", "label": "What concerns me?", "type": "long", "min": 20}, {"key": "cd1_have", "label": "What skills do I already have?", "type": "long", "min": 20}, {"key": "cd1_need", "label": "What skills do I need?", "type": "long", "min": 20}, {"key": "cd1_week", "label": "What would a typical working week involve?", "type": "long", "min": 20}, {"key": "cd1_first", "label": "What first opportunity could I realistically pursue?", "type": "long", "min": 20}]}, {"title": "Role 2", "section": "market", "fields": [{"key": "cd2_role", "label": "The role", "type": "short", "min": 6}, {"key": "cd2_attract", "label": "What attracts me?", "type": "long", "min": 20}, {"key": "cd2_concern", "label": "What concerns me?", "type": "long", "min": 20}, {"key": "cd2_have", "label": "What skills do I already have?", "type": "long", "min": 20}, {"key": "cd2_need", "label": "What skills do I need?", "type": "long", "min": 20}, {"key": "cd2_week", "label": "What would a typical working week involve?", "type": "long", "min": 20}, {"key": "cd2_first", "label": "What first opportunity could I realistically pursue?", "type": "long", "min": 20}]}, {"title": "Role 3", "section": "market", "fields": [{"key": "cd3_role", "label": "The role", "type": "short", "min": 6}, {"key": "cd3_attract", "label": "What attracts me?", "type": "long", "min": 20}, {"key": "cd3_concern", "label": "What concerns me?", "type": "long", "min": 20}, {"key": "cd3_have", "label": "What skills do I already have?", "type": "long", "min": 20}, {"key": "cd3_need", "label": "What skills do I need?", "type": "long", "min": 20}, {"key": "cd3_week", "label": "What would a typical working week involve?", "type": "long", "min": 20}, {"key": "cd3_first", "label": "What first opportunity could I realistically pursue?", "type": "long", "min": 20}]}, {"title": "My choice", "section": "market", "fields": [{"key": "cd_most", "label": "The role I want to investigate most, and why", "type": "long", "min": 30}]}]}}, {"heading": "Chapter 3: Your Transferable Skills", "body": "<p><b>Your previous career is not something to hide</b></p><p>It may be your strongest asset. The mistake is saying <em>\"I have no yachting experience.\"</em> Instead ask: <b>\"What professional problems have I already learned to solve?\"</b></p><p><b>The transferable skills map</b></p><p>&bull; <b>Sales:</b> previously selling software to business clients. Yachting relevance: consultative selling, pipeline management, negotiation, follow-up and client relationships.<br/>&bull; <b>Hospitality:</b> previously managing a luxury hotel guest experience. Relevance: anticipating needs, discretion, service standards and relationship management.<br/>&bull; <b>Finance:</b> previously advising high-value clients. Relevance: financial communication, attention to detail, trust and commercial understanding.<br/>&bull; <b>Real estate:</b> previously selling high-value property. Relevance: asset presentation, buyer qualification, negotiation, market analysis and transactions.<br/>&bull; <b>Marketing:</b> previously managing luxury brand campaigns. Relevance: positioning, storytelling, digital marketing and lead generation.<br/>&bull; <b>Project management:</b> previously coordinating complex projects. Relevance: managing multiple stakeholders, deadlines, documentation and unexpected issues.</p><p><b>Your skills inventory</b></p><p>For each existing skill, write the evidence and how it could help in yachting. Do not write <em>\"I am good with people.\"</em> Write: <em>\"Managed 25 corporate clients across three regions and maintained relationships through a 6 to 12 month sales cycle.\"</em> <b>Evidence is more persuasive than adjectives.</b></p>", "q": "Which is the stronger way to describe a skill?", "opts": ["\"I am good with people.\"", "\"I am passionate and hardworking.\"", "With specific evidence, such as managing 25 corporate clients through a 6 to 12 month sales cycle", "\"I have no yachting experience, but I am keen.\""], "correct": 2}, {"heading": "Exercise: Your Skills Inventory", "body": "<p><b>Complete the table</b></p><p>List at least five existing skills. For each, give the evidence and how it could help in yachting.</p>", "exercise": {"intro": "Evidence, not adjectives.", "groups": [{"title": "Skill 1", "section": "profile", "fields": [{"key": "sk1_skill", "label": "My existing skill", "type": "short", "min": 6}, {"key": "sk1_ev", "label": "Evidence (numbers, scale, results)", "type": "long", "min": 25}, {"key": "sk1_use", "label": "How it could help in yachting", "type": "long", "min": 25}]}, {"title": "Skill 2", "section": "profile", "fields": [{"key": "sk2_skill", "label": "My existing skill", "type": "short", "min": 6}, {"key": "sk2_ev", "label": "Evidence (numbers, scale, results)", "type": "long", "min": 25}, {"key": "sk2_use", "label": "How it could help in yachting", "type": "long", "min": 25}]}, {"title": "Skill 3", "section": "profile", "fields": [{"key": "sk3_skill", "label": "My existing skill", "type": "short", "min": 6}, {"key": "sk3_ev", "label": "Evidence (numbers, scale, results)", "type": "long", "min": 25}, {"key": "sk3_use", "label": "How it could help in yachting", "type": "long", "min": 25}]}, {"title": "Skill 4", "section": "profile", "fields": [{"key": "sk4_skill", "label": "My existing skill", "type": "short", "min": 6}, {"key": "sk4_ev", "label": "Evidence (numbers, scale, results)", "type": "long", "min": 25}, {"key": "sk4_use", "label": "How it could help in yachting", "type": "long", "min": 25}]}, {"title": "Skill 5", "section": "profile", "fields": [{"key": "sk5_skill", "label": "My existing skill", "type": "short", "min": 6}, {"key": "sk5_ev", "label": "Evidence (numbers, scale, results)", "type": "long", "min": 25}, {"key": "sk5_use", "label": "How it could help in yachting", "type": "long", "min": 25}]}]}}, {"heading": "Chapter 4: Build Your Professional Identity", "body": "<p><b>Don't introduce yourself by what you lack</b></p><p>A career changer often makes the same mistake: they introduce themselves by explaining what they <b>don't</b> have. <em>\"I've never worked in yachting.\"</em> That may be true. But it isn't a professional identity.</p><p><b>Your new introduction</b></p><p>It should answer: who are you, what have you done, what skills have you developed, why yachting, and what are you trying to do next? For example:</p><p><em>\"I've spent the last eight years in luxury hospitality, where I've managed high-value client relationships and complex service requirements. I'm now looking to move into yacht brokerage because I'm interested in combining relationship management, commercial negotiation and the luxury market. I've been building my yacht-market knowledge and I'm looking to join a brokerage where I can learn the business properly and contribute from day one.\"</em></p><p>Notice what this does not say: <em>\"I'm passionate about yachts and would love an opportunity.\"</em> Passion can be useful. Evidence is stronger.</p><p><b>The \"Why yachting?\" test</b></p><p>Your answer should survive the follow-up question: <em>\"Why yachting specifically?\"</em> Avoid answers based entirely on travel, luxury, money, lifestyle or boats being beautiful. These may be genuine interests. But they don't explain why you would be valuable professionally.</p>", "q": "Why is \"I'm passionate about yachts and would love an opportunity\" a weak introduction?", "opts": ["Because passion is inappropriate in business", "Because it is too long", "Because it mentions yachts", "Passion can help, but it is not evidence of professional value"], "correct": 3}, {"heading": "Exercise: Build Your Professional Story", "body": "<p><b>A 100 to 150 word introduction</b></p><p>Include your past, your skills, why yachting, evidence of serious interest and the opportunity you are looking for. Then test it against the follow-up: <em>\"Why yachting specifically?\"</em></p>", "exercise": {"intro": "No lifestyle answers. Evidence and professional value.", "groups": [{"title": "My story, part by part", "section": "profile", "fields": [{"key": "ps_past", "label": "PAST: what have you done?", "type": "long", "min": 25}, {"key": "ps_skills", "label": "SKILLS: what can you already do?", "type": "long", "min": 25}, {"key": "ps_why", "label": "WHY YACHTING: why are you making this move?", "type": "long", "min": 30}, {"key": "ps_ev", "label": "EVIDENCE: what have you done to show serious interest?", "type": "long", "min": 30}, {"key": "ps_next", "label": "NEXT: what opportunity are you looking for?", "type": "long", "min": 20}]}, {"title": "My introduction", "section": "profile", "fields": [{"key": "ps_intro", "label": "My professional introduction (100 to 150 words)", "type": "long", "min": 350}, {"key": "ps_test", "label": "My answer to: \"Why yachting specifically?\"", "type": "long", "min": 40}]}]}}, {"heading": "Chapter 5: Find Your Target Companies", "body": "<p><b>Do not apply everywhere</b></p><p>Build a target market. Your objective is to identify organisations where your background, interests and developing skills could realistically create a conversation.</p><p><b>What to research</b></p><p>For every target company, investigate its brokerage focus, location, yacht size range, new build versus brokerage, charter activity, international offices, market reputation, type of clientele, current team, visible areas of expertise, career opportunities and recent activity. Don't simply collect names. Understand the business.</p><p><b>Your target company matrix</b></p><p>Create a list of <b>15 companies.</b> For each: company, location, focus, why it is relevant to me, contact, evidence of research and next action.</p><p><b>Go beyond the website</b></p><p>Look at team biographies, yacht listings, recent transactions, industry events, professional networking profiles, press announcements, company offices and areas of specialisation. The objective is to understand the organisation before contacting it.</p>", "q": "What should you do before contacting a brokerage?", "opts": ["Send your CV immediately", "Research and understand the business, not just collect its name", "Apply to as many companies as possible", "Wait for them to advertise a role"], "correct": 1}, {"heading": "Exercise: Your Target Company Matrix", "body": "<p><b>Fifteen companies</b></p><p>For each, write one line covering: <b>Company | Location | Focus | Why relevant to me | Contact | Evidence of research | Next action.</b></p>", "exercise": {"intro": "One company per field. Real research, not just names.", "groups": [{"title": "My fifteen target companies", "section": "market", "fields": [{"key": "tc_01", "label": "Company 1", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_02", "label": "Company 2", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_03", "label": "Company 3", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_04", "label": "Company 4", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_05", "label": "Company 5", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_06", "label": "Company 6", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_07", "label": "Company 7", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_08", "label": "Company 8", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_09", "label": "Company 9", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_10", "label": "Company 10", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_11", "label": "Company 11", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_12", "label": "Company 12", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_13", "label": "Company 13", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_14", "label": "Company 14", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}, {"key": "tc_15", "label": "Company 15", "type": "long", "min": 40, "placeholder": "Company | Location | Focus | Why relevant | Contact | Evidence of research | Next action"}]}]}}, {"heading": "Chapter 6: Approach the Industry", "body": "<p><b>Where many career changers become passive</b></p><p>They send: <em>\"Dear Sir/Madam, I am interested in working for your company. Please find my CV attached.\"</em> Then they wait. A stronger approach is targeted.</p><p><b>Build a contact map</b></p><p>For each target company identify: the <b>primary contact</b> (who would realistically be relevant to your career direction), a <b>secondary contact</b> (who could provide industry insight), the <b>context</b> (why you are contacting this person specifically), the <b>value</b> you bring and the <b>ask</b> (what you are actually asking for).</p><p><b>The networking principle</b></p><p>Don't approach everyone asking for a job. Sometimes the first objective is to <b>understand.</b> Then to <b>build a relationship.</b> Then to <b>create an opportunity.</b></p><p><b>Informational conversation</b></p><p><em>\"I'm currently transitioning from luxury hospitality into yachting and have been researching brokerage in detail. I'm trying to understand what successful entry-level candidates actually do well in their first year. If you had 15 minutes, I'd value your perspective on the skills you think matter most.\"</em></p><p>That is a much easier conversation to accept than <em>\"Can you give me a job?\"</em></p><p><b>Outreach exercise</b></p><p>Write three versions, each personalised: a <b>cold email</b> (100 to 150 words), a <b>professional networking message</b> (50 to 75 words) and a <b>warm introduction request</b> (50 to 100 words).</p>", "q": "What is the purpose of an informational conversation?", "opts": ["To ask directly for a job", "To sell the contact your services", "To understand the industry and build a relationship, which can later create an opportunity", "To avoid having to apply"], "correct": 2}, {"heading": "Exercise: Contact Map and Outreach", "body": "<p><b>Build the map, then write three messages</b></p><p>Pick one target company. Complete the contact map. Then write a cold email (100 to 150 words), a networking message (50 to 75 words) and a warm introduction request (50 to 100 words). Each should be personalised.</p>", "exercise": {"intro": "Personalised. Not \"Dear Sir/Madam\".", "groups": [{"title": "Contact map for one company", "section": "services", "fields": [{"key": "cm_co", "label": "The company", "type": "short", "min": 4}, {"key": "cm_primary", "label": "Primary contact", "type": "short", "min": 6}, {"key": "cm_secondary", "label": "Secondary contact", "type": "short", "min": 6}, {"key": "cm_context", "label": "Context: why this person?", "type": "long", "min": 20}, {"key": "cm_value", "label": "Value: what do you bring?", "type": "long", "min": 20}, {"key": "cm_ask", "label": "Ask: what are you actually asking for?", "type": "long", "min": 20}]}, {"title": "Three versions", "section": "services", "fields": [{"key": "ou_cold", "label": "1. Cold email (100 to 150 words)", "type": "long", "min": 350}, {"key": "ou_net", "label": "2. Professional networking message (50 to 75 words)", "type": "long", "min": 180}, {"key": "ou_warm", "label": "3. Warm introduction request (50 to 100 words)", "type": "long", "min": 180}]}]}}, {"heading": "Chapter 7: Prepare for the Interview", "body": "<p><b>It is not only about yacht terminology</b></p><p>The interviewer may be trying to understand how you think, how you communicate, whether you listen, whether you understand the commercial nature of brokerage, whether you can handle rejection, whether you are genuinely interested, whether you understand what the job involves and whether you can learn.</p><p><b>Questions to expect</b></p><p>&bull; <b>\"Why yachting?\"</b> Connect your previous experience to the new industry.<br/>&bull; <b>\"Why brokerage?\"</b> Explain what attracts you to the actual work.<br/>&bull; <b>\"Why should we hire someone without yacht experience?\"</b> Don't become defensive. Explain the skills you have and what you have done to close the knowledge gap.<br/>&bull; <b>\"What do you know about our company?\"</b> This tests preparation.<br/>&bull; <b>\"Tell me about a difficult client.\"</b> Use a real example.<br/>&bull; <b>\"Tell me about a time you lost a sale.\"</b> Show reflection.<br/>&bull; <b>\"How do you handle rejection?\"</b> Give evidence.<br/>&bull; <b>\"What have you done to learn about yachting?\"</b> This is where your Academy work becomes useful.</p><p><b>The STAR method</b></p><p>For experience-based questions: <b>S, situation</b> (what was happening?), <b>T, task</b> (what were you responsible for?), <b>A, action</b> (what did you actually do?), <b>R, result</b> (what happened?). Then add <b>L, learning</b> (what did you learn?). The final step is particularly valuable during a career change.</p><p><b>Your career-change story</b></p><p>You need one coherent story: <b>where I have been → what I learned → why I want to change → why yachting → what I have done to prepare → what I can contribute → what I want to learn next.</b> If those pieces connect naturally, the career change becomes easier for another person to understand.</p>", "q": "What does the extra \"L\" in STAR stand for?", "opts": ["Learning, what you took from the experience", "Loyalty", "Leadership", "Location"], "correct": 0}, {"heading": "Exercise: Interview Answers", "body": "<p><b>Write your answers</b></p><p>Answer the ten questions. Use STAR plus learning for experience questions. Then write your career-change story and practise each answer aloud.</p>", "exercise": {"intro": "Real examples. Practise them aloud afterwards.", "groups": [{"title": "Interview answers", "section": "services", "fields": [{"key": "iv_1", "label": "1. Why are you moving into yachting?", "type": "long", "min": 60}, {"key": "iv_2", "label": "2. Why yacht brokerage?", "type": "long", "min": 60}, {"key": "iv_3", "label": "3. What do you understand about the broker's job?", "type": "long", "min": 60}, {"key": "iv_4", "label": "4. What transferable skills do you bring?", "type": "long", "min": 60}, {"key": "iv_5", "label": "5. What is your biggest knowledge gap?", "type": "long", "min": 40}, {"key": "iv_6", "label": "6. What have you done to close it?", "type": "long", "min": 40}, {"key": "iv_7", "label": "7. Tell me about a difficult client (STAR + learning).", "type": "long", "min": 100}, {"key": "iv_8", "label": "8. Tell me about a commercial failure (STAR + learning).", "type": "long", "min": 100}, {"key": "iv_9", "label": "9. How do you handle rejection?", "type": "long", "min": 60}, {"key": "iv_10", "label": "10. Where would you like to be in three years?", "type": "long", "min": 40}]}, {"title": "My career-change story", "section": "profile", "fields": [{"key": "cs_story", "label": "Where I have been, what I learned, why I want to change, why yachting, what I have done to prepare, what I can contribute, what I want to learn next", "type": "long", "min": 200}]}]}}, {"heading": "The Complete Career Challenge", "body": "<p><b>From career changer to candidate</b></p><p>You are now going to build your first realistic entry strategy. Imagine you are preparing to enter the yacht industry within the next six months. You have completed this Academy. You have no direct professional yacht-brokerage experience. You do have previous professional experience that you can translate into relevant skills. Your task is to turn that background into a credible market entry plan.</p><p><b>Timing: 90 minutes</b></p><p>Career-fit assessment (15 min), transferable-skills analysis (15), company research (20), professional positioning (15), outreach strategy (15) and interview preparation (10).</p><p><b>What you will submit</b></p><p>A career-fit reflection, your transferable skills, three possible routes, a target company list, a professional introduction, an outreach plan, interview preparation and a six-month entry plan. Much of it builds on what you have already written in this module. The next pages take you through it.</p>", "q": "What is the task in the Complete Career Challenge?", "opts": ["To apply for ten jobs in a day", "To turn your background into a credible market entry plan", "To write a CV", "To prove you have yacht brokerage experience"], "correct": 1}, {"heading": "Challenge 1 to 3: Fit, Skills and Routes", "body": "<p><b>1. Career-fit reflection (250 to 300 words)</b></p><p>What attracts me to yacht brokerage? What concerns me? Which parts fit my strengths? Which may challenge me? What evidence do I have that I actually enjoy the work?</p><p><b>2. My transferable skills</b></p><p>At least five skills. For each: skill, evidence, relevance to yachting and an example of how you would demonstrate it in an interview.</p><p><b>3. My three possible routes</b></p><p>Three yachting career directions. For each: why it interests you, what you already bring, what you need to learn and what entry opportunity could get you started. Then say which you will investigate first. This is a direction, not a permanent commitment.</p>", "exercise": {"intro": "Reuse and sharpen what you wrote earlier in this module.", "groups": [{"title": "1. Career-fit reflection", "section": "profile", "fields": [{"key": "c1_text", "label": "Your reflection (250 to 300 words)", "type": "long", "min": 800}]}, {"title": "2. Transferable skill 1", "section": "profile", "fields": [{"key": "c2_1_skill", "label": "Skill", "type": "short", "min": 6}, {"key": "c2_1_ev", "label": "Evidence", "type": "long", "min": 25}, {"key": "c2_1_rel", "label": "Relevance to yachting", "type": "long", "min": 25}, {"key": "c2_1_int", "label": "How you would demonstrate it in an interview", "type": "long", "min": 25}]}, {"title": "2. Transferable skill 2", "section": "profile", "fields": [{"key": "c2_2_skill", "label": "Skill", "type": "short", "min": 6}, {"key": "c2_2_ev", "label": "Evidence", "type": "long", "min": 25}, {"key": "c2_2_rel", "label": "Relevance to yachting", "type": "long", "min": 25}, {"key": "c2_2_int", "label": "How you would demonstrate it in an interview", "type": "long", "min": 25}]}, {"title": "2. Transferable skill 3", "section": "profile", "fields": [{"key": "c2_3_skill", "label": "Skill", "type": "short", "min": 6}, {"key": "c2_3_ev", "label": "Evidence", "type": "long", "min": 25}, {"key": "c2_3_rel", "label": "Relevance to yachting", "type": "long", "min": 25}, {"key": "c2_3_int", "label": "How you would demonstrate it in an interview", "type": "long", "min": 25}]}, {"title": "2. Transferable skill 4", "section": "profile", "fields": [{"key": "c2_4_skill", "label": "Skill", "type": "short", "min": 6}, {"key": "c2_4_ev", "label": "Evidence", "type": "long", "min": 25}, {"key": "c2_4_rel", "label": "Relevance to yachting", "type": "long", "min": 25}, {"key": "c2_4_int", "label": "How you would demonstrate it in an interview", "type": "long", "min": 25}]}, {"title": "2. Transferable skill 5", "section": "profile", "fields": [{"key": "c2_5_skill", "label": "Skill", "type": "short", "min": 6}, {"key": "c2_5_ev", "label": "Evidence", "type": "long", "min": 25}, {"key": "c2_5_rel", "label": "Relevance to yachting", "type": "long", "min": 25}, {"key": "c2_5_int", "label": "How you would demonstrate it in an interview", "type": "long", "min": 25}]}, {"title": "3. Route 1", "section": "market", "fields": [{"key": "c3_1_route", "label": "Career direction", "type": "short", "min": 6}, {"key": "c3_1_why", "label": "Why it interests me", "type": "long", "min": 20}, {"key": "c3_1_bring", "label": "What I already bring", "type": "long", "min": 20}, {"key": "c3_1_learn", "label": "What I need to learn", "type": "long", "min": 20}, {"key": "c3_1_entry", "label": "Entry opportunity that could get me started", "type": "long", "min": 20}]}, {"title": "3. Route 2", "section": "market", "fields": [{"key": "c3_2_route", "label": "Career direction", "type": "short", "min": 6}, {"key": "c3_2_why", "label": "Why it interests me", "type": "long", "min": 20}, {"key": "c3_2_bring", "label": "What I already bring", "type": "long", "min": 20}, {"key": "c3_2_learn", "label": "What I need to learn", "type": "long", "min": 20}, {"key": "c3_2_entry", "label": "Entry opportunity that could get me started", "type": "long", "min": 20}]}, {"title": "3. Route 3", "section": "market", "fields": [{"key": "c3_3_route", "label": "Career direction", "type": "short", "min": 6}, {"key": "c3_3_why", "label": "Why it interests me", "type": "long", "min": 20}, {"key": "c3_3_bring", "label": "What I already bring", "type": "long", "min": 20}, {"key": "c3_3_learn", "label": "What I need to learn", "type": "long", "min": 20}, {"key": "c3_3_entry", "label": "Entry opportunity that could get me started", "type": "long", "min": 20}]}, {"title": "First direction", "section": "market", "fields": [{"key": "c3_first", "label": "The direction I will investigate first, and why", "type": "long", "min": 30}]}]}}, {"heading": "Challenge 4 to 6: Companies, Introduction and Outreach", "body": "<p><b>4. Target company list</b></p><p>Your fifteen companies are in your matrix. Here, name your five priority companies and the next action and date for each.</p><p><b>5. Professional introduction (100 to 150 words)</b></p><p>Your final version: background, transferable skills, why yachting, why brokerage or your chosen direction, what you have done to prepare and what you are looking for next.</p><p><b>6. Outreach plan</b></p><p>Final versions of a cold email (100 to 150 words), a networking message (50 to 75 words) and a warm introduction request (50 to 100 words). Then say who you would send each to, why, when, and what you would do if there is no response.</p>", "exercise": {"intro": "Personalised, specific and measurable.", "groups": [{"title": "4. My five priority companies", "section": "market", "fields": [{"key": "c4_1", "label": "Priority 1: company, next action and date", "type": "long", "min": 30}, {"key": "c4_2", "label": "Priority 2: company, next action and date", "type": "long", "min": 30}, {"key": "c4_3", "label": "Priority 3: company, next action and date", "type": "long", "min": 30}, {"key": "c4_4", "label": "Priority 4: company, next action and date", "type": "long", "min": 30}, {"key": "c4_5", "label": "Priority 5: company, next action and date", "type": "long", "min": 30}]}, {"title": "5. Professional introduction", "section": "profile", "fields": [{"key": "c5_intro", "label": "Your professional introduction (100 to 150 words)", "type": "long", "min": 350}]}, {"title": "6. Outreach plan", "section": "services", "fields": [{"key": "c6_cold", "label": "Cold email (100 to 150 words)", "type": "long", "min": 350}, {"key": "c6_net", "label": "Networking message (50 to 75 words)", "type": "long", "min": 180}, {"key": "c6_warm", "label": "Warm introduction request (50 to 100 words)", "type": "long", "min": 180}, {"key": "c6_who", "label": "Who you would send each to, and why", "type": "long", "min": 60}, {"key": "c6_when", "label": "When you would send each", "type": "long", "min": 30}, {"key": "c6_none", "label": "What you would do if there is no response", "type": "long", "min": 40}]}]}}, {"heading": "Challenge 7: Interview Preparation", "body": "<p><b>7. Interview preparation</b></p><p>Choose five likely interview questions. Write your answers using <b>Situation, Task, Action, Result, Learning.</b> At least two answers must use genuine examples from your previous career or life experience.</p>", "exercise": {"intro": "At least two answers must use genuine examples.", "groups": [{"title": "Question 1", "section": "services", "fields": [{"key": "c7_1_q", "label": "The question", "type": "short", "min": 10}, {"key": "c7_1_a", "label": "Your answer (Situation, Task, Action, Result, Learning)", "type": "long", "min": 120}]}, {"title": "Question 2", "section": "services", "fields": [{"key": "c7_2_q", "label": "The question", "type": "short", "min": 10}, {"key": "c7_2_a", "label": "Your answer (Situation, Task, Action, Result, Learning)", "type": "long", "min": 120}]}, {"title": "Question 3", "section": "services", "fields": [{"key": "c7_3_q", "label": "The question", "type": "short", "min": 10}, {"key": "c7_3_a", "label": "Your answer (Situation, Task, Action, Result, Learning)", "type": "long", "min": 120}]}, {"title": "Question 4", "section": "services", "fields": [{"key": "c7_4_q", "label": "The question", "type": "short", "min": 10}, {"key": "c7_4_a", "label": "Your answer (Situation, Task, Action, Result, Learning)", "type": "long", "min": 120}]}, {"title": "Question 5", "section": "services", "fields": [{"key": "c7_5_q", "label": "The question", "type": "short", "min": 10}, {"key": "c7_5_a", "label": "Your answer (Situation, Task, Action, Result, Learning)", "type": "long", "min": 120}]}]}}, {"heading": "Challenge 8: Your Six-Month Entry Plan", "body": "<p><b>8. Six-month entry plan</b></p><p>Break your plan into months. It should contain measurable actions. Not <em>\"Network more.\"</em> Instead: <em>\"Contact five relevant industry professionals each week and request two informational conversations per month.\"</em></p>", "exercise": {"intro": "Measurable, sequenced and realistic.", "groups": [{"title": "My six-month plan", "section": "profile", "fields": [{"key": "sm_1", "label": "Month 1: knowledge and positioning", "type": "long", "min": 60}, {"key": "sm_2", "label": "Month 2: research and networking", "type": "long", "min": 60}, {"key": "sm_3", "label": "Month 3: industry conversations", "type": "long", "min": 60}, {"key": "sm_4", "label": "Month 4: applications and targeted outreach", "type": "long", "min": 60}, {"key": "sm_5", "label": "Month 5: interviews, follow-up and relationship building", "type": "long", "min": 60}, {"key": "sm_6", "label": "Month 6: review, refine and expand the strategy", "type": "long", "min": 60}]}]}}, {"heading": "Assessment Rubric and Model Answers", "body": "<p><b>What the challenge assesses</b></p><p>This assessment is not about having an impressive CV. It is about demonstrating that you understand how to turn your existing professional capital into a credible entry strategy. The rubric moves from developing to competent to strong:</p><p>&bull; <b>Career fit:</b> from generic reasons, to genuine attractions and concerns, to a realistic understanding of both opportunity and difficulty.<br/>&bull; <b>Transferable skills:</b> from listing skills without evidence, to connecting them to yachting, to specific evidence and commercial relevance.<br/>&bull; <b>Career direction:</b> from choosing a role based mainly on interest, to comparing several paths, to explaining why different paths fit different strengths.<br/>&bull; <b>Company research:</b> from collecting names, to researching relevant businesses, to genuine understanding of target organisations.<br/>&bull; <b>Professional identity:</b> from focusing on lack of experience, to explaining background and motivation, to a coherent, evidence-based career-change story.<br/>&bull; <b>Outreach:</b> from generic application language, to personalised and professional, to clearly explaining relevance, context and purpose.<br/>&bull; <b>Interview preparation:</b> from theoretical answers, to relevant examples, to specific evidence, reflection and learning.<br/>&bull; <b>Action plan:</b> from broad intentions, to specific actions, to measurable, sequenced and realistic actions.<br/>&bull; <b>Professionalism:</b> from inconsistent or vague, to clear and appropriate, to concise, credible, discreet and commercially aware.<br/>&bull; <b>Self-awareness:</b> from overconfident or overly negative, to identifying strengths and gaps, to a balanced understanding of strengths, gaps and development needs.</p><p><b>What makes a strong submission?</b></p><p>A strong career plan does not say <em>\"I really want to work in yachting.\"</em> It demonstrates why, why you, why this part of yachting, why this type of company, what you have already done, what you still need to learn, who you will approach and what you will do next. That is the difference between interest and professional intent.</p><p><b>Model answer: professional introduction</b></p><p><em>\"I've spent the last several years working in a client-facing commercial environment, where I've developed experience in relationship management, negotiation and managing complex client requirements. I'm now looking to transfer those skills into yacht brokerage. What attracts me is the combination of high-value advisory sales, international relationships and the need to understand both the client and the asset. Since deciding to explore the industry, I've been deliberately building my knowledge of yachts, the brokerage process and the wider yachting ecosystem. I'm now looking for an opportunity where I can contribute the commercial and client skills I already have while developing the technical and market knowledge required to become a credible yacht broker.\"</em></p><p>Notice that the candidate does not pretend to have experience they do not have. They demonstrate preparation.</p><p><b>Model answer: \"Why should we hire you without yacht experience?\"</b></p><p><em>\"I wouldn't claim that I know the yacht market as well as someone who has already worked in it. What I can demonstrate is that I already know how to build client relationships, manage a sales process, communicate with demanding clients and follow through on complex commercial opportunities. I've also taken the time to understand what brokerage actually involves rather than simply being attracted to the lifestyle. I know I have a knowledge gap, particularly around the technical and transactional side, and I'm prepared to work on that. My objective would be to bring immediate value through the skills I already possess while learning the industry properly.\"</em></p><p>The point is not to disguise the gap. It is to show that you understand it and have a plan to close it.</p>", "q": "What does the model answer to \"Why should we hire you without yacht experience?\" do?", "opts": ["Denies that there is any gap", "Focuses on how much the candidate loves yachts", "Avoids mentioning experience at all", "Acknowledges the gap honestly, shows relevant skills and explains the plan to close it"], "correct": 3}, {"heading": "Broker's Notebook: Module 9", "body": "<p><b>Broker's notebook</b></p><p>Write short answers.</p>", "exercise": {"intro": "Short and honest.", "groups": [{"title": "My notebook", "section": "profile", "fields": [{"key": "n9_1", "label": "What part of my previous career has the greatest relevance to yachting?", "type": "long", "min": 20}, {"key": "n9_2", "label": "What is my biggest transferable strength?", "type": "long", "min": 20}, {"key": "n9_3", "label": "What is my biggest knowledge gap?", "type": "long", "min": 20}, {"key": "n9_4", "label": "What evidence do I have that I am serious about this career change?", "type": "long", "min": 20}, {"key": "n9_5", "label": "What part of yacht brokerage might I be underestimating?", "type": "long", "min": 20}, {"key": "n9_6", "label": "What would make me decide that brokerage is not the right route?", "type": "long", "min": 20}, {"key": "n9_7", "label": "Which yachting role would I investigate if brokerage did not work out?", "type": "long", "min": 15}, {"key": "n9_8", "label": "What would I like a brokerage owner or director to remember about me after a first meeting?", "type": "long", "min": 20}]}]}}, {"heading": "Professional Output: My Yachting Career Entry Pack", "body": "<p><b>My Yachting Career Entry Pack</b></p><p>A concise three-page professional pack: your profile, your target market and your action plan. This becomes one of the most important documents in your Broker Portfolio. It is not your final CV. It is your career strategy.</p>", "exercise": {"intro": "Three pages: profile, target market, action plan.", "groups": [{"title": "Page 1: My professional profile", "section": "profile", "fields": [{"key": "ep_head", "label": "Professional headline", "type": "short", "min": 15}, {"key": "ep_intro", "label": "100-word introduction", "type": "long", "min": 250}, {"key": "ep_skills", "label": "Five transferable skills, with evidence for each", "type": "long", "min": 150}, {"key": "ep_why", "label": "Why yachting", "type": "long", "min": 40}]}, {"title": "Page 2: My target market", "section": "market", "fields": [{"key": "ep_dir", "label": "Preferred career direction", "type": "short", "min": 10}, {"key": "ep_comp", "label": "Target companies (summarise the fifteen, highlight your priorities)", "type": "long", "min": 100}, {"key": "ep_contacts", "label": "Priority contacts", "type": "long", "min": 40}, {"key": "ep_notes", "label": "Research notes", "type": "long", "min": 40}, {"key": "ep_netobj", "label": "Networking objectives", "type": "long", "min": 40}]}, {"title": "Page 3: My action plan", "section": "services", "fields": [{"key": "ep_out", "label": "Outreach strategy", "type": "long", "min": 60}, {"key": "ep_intprep", "label": "Interview preparation", "type": "long", "min": 60}, {"key": "ep_time", "label": "Six-month timeline", "type": "long", "min": 80}, {"key": "ep_weekly", "label": "Weekly activity targets", "type": "long", "min": 40}, {"key": "ep_next5", "label": "Next five actions", "type": "long", "min": 60}]}]}}, {"heading": "Final Reflection and What Comes Next", "body": "<p><b>Module 9: final reflection</b></p><p>Take a step back. At the beginning of the Academy, you were asking <em>\"What is yachting?\"</em> Then <em>\"How does a yacht work?\"</em> Then <em>\"How does the market work?\"</em> Then <em>\"How do I understand a client?\"</em> Then <em>\"Can I think like a broker?\"</em> Then <em>\"Can I communicate like one?\"</em> Now you are asking: <b>\"Where could I fit?\"</b> That is progress.</p><p>But don't confuse completing an academy with being ready to stop learning. Your first professional opportunity may be a brokerage role, an assistant position, an internship, a junior commercial role, charter, yacht management, marketing, operations or another route into the industry. The objective is not to force yourself into one job title. The objective is to find the <b>right entry point</b> and begin building real industry experience.</p><p><b>What comes next</b></p><p>You have now built a career strategy. The final question is: <b>what am I actually going to do next?</b></p><p><b>Module 10: Your First Opportunity.</b> <em>Your graduation is an action plan.</em> You will turn everything you have built into a clear career direction, a target list, a professional network, personalised outreach, a final broker challenge, a 30 / 60 / 90-day plan and your first 10 real opportunities. The Academy will finish not with <em>\"Congratulations. You are a yacht broker.\"</em> But with something much more useful: <b>\"Here is what I am going to do next.\"</b></p>", "q": "How does the Academy plan to end, according to the Module 10 preview?", "opts": ["With an action plan for what you will do next, not a declaration that you are a broker", "With a broker qualification exam", "With a guaranteed job offer", "With a final yacht sale"], "correct": 0}]$json$;
  v_final jsonb := $json$[{"q": "Why should you assess career fit before building an entry strategy?", "opts": ["Because brokerages ask for a fit score", "A career change is costly in time, energy, reputation and emotion, so you should test whether you want the working life first", "Because career fit is the same as skills", "Because entry strategies are never needed"], "correct": 1}, {"q": "What is a transferable skill?", "opts": ["A skill from a previous career or experience that has value in a different industry", "A skill you can only use in one industry", "A certificate you receive after training", "A personality trait you were born with"], "correct": 0}, {"q": "Why is evidence stronger than simply claiming a skill?", "opts": ["Because employers prefer long CVs", "Because claims are never allowed", "Because evidence hides gaps in experience", "Specific evidence, such as numbers, scale and results, is credible and shows what you have actually done"], "correct": 3}, {"q": "What should a professional introduction contain?", "opts": ["Who you are, what you have done, your skills, why yachting and what you are looking for next", "Only your passion for boats", "A list of the companies you dislike", "Your salary expectations"], "correct": 0}, {"q": "Why should you research a brokerage before contacting it?", "opts": ["To copy its client list", "To avoid contacting anyone", "To understand the business and personalise your approach, rather than sending generic applications", "Because research replaces outreach"], "correct": 2}, {"q": "What is the purpose of an informational conversation?", "opts": ["To ask directly for a job", "To understand the industry and build a relationship that may later create an opportunity", "To sell your services to the contact", "To avoid a formal interview"], "correct": 1}, {"q": "Why is \"I love yachts\" insufficient as a professional pitch?", "opts": ["Because loving yachts is a disadvantage", "Because employers dislike enthusiasm", "Because it is too short", "It describes interest, not professional value, and does not explain why you would be useful"], "correct": 3}, {"q": "What does STAR stand for?", "opts": ["Situation, Task, Action, Result", "Skills, Targets, Actions, Rewards", "Strategy, Timing, Approach, Response", "Story, Tone, Answer, Review"], "correct": 0}, {"q": "Why should your outreach be personalised?", "opts": ["Because generic messages are illegal", "Because it lets you skip research", "It shows relevance, research and purpose, and is far more likely to earn a reply than a generic message", "Because it makes the message longer"], "correct": 2}, {"q": "What makes a career plan measurable?", "opts": ["Broad intentions like \"network more\"", "Specific actions with numbers and timing, such as contacting five professionals each week", "A long list of goals without dates", "A plan that avoids deadlines"], "correct": 1}]$json$;
begin
  select id into v_module from public.academy_modules where track = 'yachts' and module_number = 9;
  if v_module is null then
    raise exception 'Yachts module 9 not found';
  end if;

  update public.academy_modules
     set title = 'Build Your Career', description = 'Could I realistically enter this industry?'
   where id = v_module;

  delete from public.academy_module_pages where module_id = v_module;
  delete from public.academy_quiz_questions where module_id = v_module;

  for rec in select * from jsonb_array_elements(v_pages) loop
    n := n + 1;
    if rec ? 'exercise' then
      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id, exercise)
      values (v_module, n, rec->>'heading', rec->>'body', null, rec->'exercise');
    else
      insert into public.academy_quiz_questions (module_id, question_text, order_index, stage, page_number)
      values (v_module, rec->>'q', 0, 'checkpoint', n)
      returning id into v_q;

      for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
        insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
        values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
      end loop;

      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id)
      values (v_module, n, rec->>'heading', rec->>'body', v_q);
    end if;
  end loop;

  n := 0;
  for rec in select * from jsonb_array_elements(v_final) loop
    n := n + 1;
    insert into public.academy_quiz_questions (module_id, question_text, order_index, stage)
    values (v_module, rec->>'q', n - 1, 'final')
    returning id into v_q;

    for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
      insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
      values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
    end loop;
  end loop;
end
$mig$;
